  `nama_kegiatan` varchar(255) DEFAULT NULL,
  `kode_sub_kegiatan` varchar(50) DEFAULT NULL,
  `nama_sub_kegiatan` varchar(255) DEFAULT NULL,
  `total_belanja` decimal(18,2) DEFAULT 0.00,
