--
-- Table structure for table `belanja_rincian`
--

DROP TABLE IF EXISTS `belanja_rincian`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `belanja_rincian` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rekening_id` int(11) NOT NULL,
  `uraian` text DEFAULT NULL,
  `koefisien` decimal(10,2) DEFAULT 0.00,
  `harga_satuan` decimal(18,2) DEFAULT 0.00,
  `ppn` decimal(5,2) DEFAULT 0.00,
  `jumlah` decimal(18,2) DEFAULT 0.00,
  `sumber_dana` varchar(255) DEFAULT NULL,
  `jenis_standar_harga` varchar(100) DEFAULT NULL,
  `komponen` varchar(255) DEFAULT NULL,
  `spesifikasi_komponen` text DEFAULT NULL,
  `satuan` varchar(50) DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `koefisien_volume` decimal(10,2) DEFAULT 0.00,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
